use std::fs

fn parse_line(line: string) -> Vec<string> {
    let chars: Vec<char> = line.chars().collect()
    let n = chars.len()
    let mut fields: Vec<string> = []
    let mut cur = ""
    let mut inq = false
    let mut i = 0
    while i < n {
        let c = chars[i]
        if inq {
            if c == '"' {
                if i + 1 < n && chars[i + 1] == '"' {
                    cur = "${cur}\""
                    i += 1
                } else {
                    inq = false
                }
            } else {
                cur = "${cur}${c}"
            }
        } else if c == '"' {
            inq = true
        } else if c == ',' {
            fields.push(cur)
            cur = ""
        } else {
            cur = "${cur}${c}"
        }
        i += 1
    }
    fields.push(cur)
    fields
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let l = line.trim_end_matches('\r')
        let fields = parse_line(l)
        let parts: Vec<string> = fields.map(|f| "[${f}]").collect()
        println("${fields.len()}: ${parts.join("|")}")
    }
}

